import json

with open("inventory.json") as f:
    inv = json.load(f)

rejected = []
with open("transactions.txt") as f:
    lines = f.read().splitlines()

for n, raw in enumerate(lines, start=1):
    parts = raw.split()
    if not parts:
        continue
    ok = False
    if len(parts) == 3 and parts[0] in ("add", "remove"):
        op, sku, qty_s = parts
        try:
            qty = int(qty_s)
        except ValueError:
            qty = None
        if qty is not None and qty >= 0:
            if op == "add":
                inv[sku] = inv.get(sku, 0) + qty
                ok = True
            else:
                if sku in inv and inv[sku] - qty >= 0:
                    inv[sku] = inv[sku] - qty
                    ok = True
    if not ok:
        rejected.append(n)

with open("inventory_after.json", "w") as f:
    json.dump(dict(sorted(inv.items())), f, indent=2)
    f.write("\n")

with open("rejected.txt", "w") as f:
    for n in rejected:
        f.write(f"{n}\n")

print("rejected:", rejected)
print(json.dumps(dict(sorted(inv.items())), indent=2))
